cat > temp_patch.py <<'EOF'
    aj_inter_type_annotation = {'@type', '@method', '@constructor', '@field'}

    tokens = {
        'root': [
            # Inter-type declarations
            (r'(declare\s+)(parents|warning|error|soft|precedence)(:)', bygroups(Keyword, Keyword, Operator)),
            # AspectJ annotations
            (r'@(before|after|around)\b', Keyword),
            # Include all Java patterns
            inherit,
        ]
    }

    def get_tokens_unprocessed(self, text):
        for index, token, value in JavaLexer.get_tokens_unprocessed(self, text):
            if token is Name and value in self.aj_keywords:
                yield index, Keyword, value
            elif token is Name.Label and value in self.aj_inter_type:
                yield index, Keyword, value[:-1]
                yield index, Operator, value[-1]
            elif token is Name.Decorator and value in self.aj_inter_type_annotation:
                yield index, Keyword, value
            else:
                yield index, token, value
EOF

# Find the right place to insert the tokens definition
line=$(grep -n "aj_inter_type_annotation" ./pygments/lexers/jvm.py | cut -d: -f1)
# Insert after that line
sed -i "${line}r temp_patch.py" ./pygments/lexers/jvm.py
rm temp_patch.py
```

